import{_ as a,o as n,c as r,a2 as o}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"AegisScan production runbooks","description":"","frontmatter":{},"headers":[],"relativePath":"operations/runbooks.md","filePath":"operations/runbooks.md","lastUpdated":null}'),t={name:"operations/runbooks.md"};function i(c,e,s,d,l,u){return n(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="aegisscan-production-runbooks" tabindex="-1">AegisScan production runbooks <a class="header-anchor" href="#aegisscan-production-runbooks" aria-label="Permalink to &quot;AegisScan production runbooks&quot;">​</a></h1><h2 id="execution-stuck-in-running" tabindex="-1">Execution stuck in <code>running</code> <a class="header-anchor" href="#execution-stuck-in-running" aria-label="Permalink to &quot;Execution stuck in `running`&quot;">​</a></h2><p>Inspect the execution and its Job. If the Job is gone or the pod restarted, restart the API so startup reconciliation marks the execution <code>failed</code> with <code>pod_restarted</code>. Preserve the execution ID and request ID in the incident.</p><h2 id="git-cache-pvc-full" tabindex="-1">Git-cache PVC full <a class="header-anchor" href="#git-cache-pvc-full" aria-label="Permalink to &quot;Git-cache PVC full&quot;">​</a></h2><p>Check PVC usage and stop new scans if necessary. Increase the PVC or remove unused repository mirrors during a maintenance window. Configure retention before enabling automated eviction.</p><h2 id="database-unreachable" tabindex="-1">Database unreachable <a class="header-anchor" href="#database-unreachable" aria-label="Permalink to &quot;Database unreachable&quot;">​</a></h2><p><code>/readyz</code> returns 503 while liveness remains healthy. Verify the configured Secret, DNS, network policy, credentials, and PostgreSQL capacity. The API fails fast on startup and reruns migrations safely after connectivity returns.</p><h2 id="idp-unreachable" tabindex="-1">IdP unreachable <a class="header-anchor" href="#idp-unreachable" aria-label="Permalink to &quot;IdP unreachable&quot;">​</a></h2><p>Existing API pods continue serving only according to cached JWKS behavior; new token verification may fail. Verify issuer/JWKS DNS and TLS, then inspect authentication-denial audit events after recovery.</p><h2 id="bad-release-rollback" tabindex="-1">Bad release rollback <a class="header-anchor" href="#bad-release-rollback" aria-label="Permalink to &quot;Bad release rollback&quot;">​</a></h2><p>Use <code>helm history</code> and <code>helm rollback</code>. Apply any required CRD changes first, then confirm <code>/healthz</code>, <code>/readyz</code>, and a read-only API request before resuming scan submissions.</p>',11)])])}const p=a(t,[["render",i]]);export{b as __pageData,p as default};
